CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '' CHECK(length(display_name)<=120), avatar_url text NOT NULL DEFAULT '' CHECK(length(avatar_url)<=2000));
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile ON public.profiles FOR ALL TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',NEW.raw_user_meta_data->>'name',''),120)); RETURN NEW; END $$;
CREATE TRIGGER alliar_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.tenants TO authenticated; GRANT ALL ON public.tenants TO service_role;
ALTER TABLE public.tenants ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('admin','member')), UNIQUE(tenant_id,user_id));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_member(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE tenant_id=t AND user_id=auth.uid()) $$;
CREATE FUNCTION public.is_tenant_admin(t uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE tenant_id=t AND user_id=auth.uid() AND role='admin') $$;
REVOKE ALL ON FUNCTION public.is_member(uuid),public.is_tenant_admin(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.is_member(uuid),public.is_tenant_admin(uuid) TO authenticated;
CREATE POLICY members_roles ON public.user_roles FOR SELECT TO authenticated USING(public.is_member(tenant_id));
CREATE POLICY members_tenants ON public.tenants FOR SELECT TO authenticated USING(public.is_member(id));
CREATE POLICY admin_tenants ON public.tenants FOR UPDATE TO authenticated USING(public.is_tenant_admin(id)) WITH CHECK(public.is_tenant_admin(id));
CREATE TABLE public.tenant_settings(tenant_id uuid PRIMARY KEY REFERENCES public.tenants ON DELETE CASCADE,structure text NOT NULL DEFAULT 'solo' CHECK(structure IN ('solo','equipe')),commission_rate numeric NOT NULL DEFAULT 0 CHECK(commission_rate BETWEEN 0 AND 100),pix_key text NOT NULL DEFAULT '' CHECK(length(pix_key)<=140));
GRANT SELECT,UPDATE ON public.tenant_settings TO authenticated; GRANT ALL ON public.tenant_settings TO service_role;
ALTER TABLE public.tenant_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY settings_read ON public.tenant_settings FOR SELECT TO authenticated USING(public.is_member(tenant_id));
CREATE POLICY settings_update ON public.tenant_settings FOR UPDATE TO authenticated USING(public.is_tenant_admin(tenant_id)) WITH CHECK(public.is_tenant_admin(tenant_id));
CREATE TABLE public.user_preferences(user_id uuid PRIMARY KEY REFERENCES public.profiles ON DELETE CASCADE,view text NOT NULL DEFAULT 'focado' CHECK(view IN ('focado','completo')),theme text NOT NULL DEFAULT 'dark' CHECK(theme IN ('dark','light')),tour_done boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE ON public.user_preferences TO authenticated; GRANT ALL ON public.user_preferences TO service_role;
ALTER TABLE public.user_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_preferences ON public.user_preferences FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.pipeline_stages(tenant_id uuid REFERENCES public.tenants ON DELETE CASCADE,id text NOT NULL CHECK(id IN ('novo','contato','proposta','negociacao','ganho')),label text NOT NULL CHECK(length(label) BETWEEN 1 AND 80),position integer NOT NULL,PRIMARY KEY(tenant_id,id));
GRANT SELECT,UPDATE ON public.pipeline_stages TO authenticated; GRANT ALL ON public.pipeline_stages TO service_role;
ALTER TABLE public.pipeline_stages ENABLE ROW LEVEL SECURITY;
CREATE POLICY stages_read ON public.pipeline_stages FOR SELECT TO authenticated USING(public.is_member(tenant_id));
CREATE POLICY stages_update ON public.pipeline_stages FOR UPDATE TO authenticated USING(public.is_tenant_admin(tenant_id)) WITH CHECK(public.is_tenant_admin(tenant_id));
CREATE TABLE public.contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants ON DELETE CASCADE,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),company text NOT NULL DEFAULT '' CHECK(length(company)<=160),phone text NOT NULL DEFAULT '' CHECK(length(phone)<=40),email text NOT NULL DEFAULT '' CHECK(length(email)<=254),UNIQUE(tenant_id,id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.contacts TO authenticated; GRANT ALL ON public.contacts TO service_role;
ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;
CREATE POLICY contacts_members ON public.contacts FOR ALL TO authenticated USING(public.is_member(tenant_id)) WITH CHECK(public.is_member(tenant_id));
CREATE TABLE public.leads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants ON DELETE CASCADE,contact_id uuid NOT NULL,value numeric NOT NULL DEFAULT 0 CHECK(value BETWEEN 0 AND 999999999),stage text NOT NULL DEFAULT 'novo',temp text NOT NULL DEFAULT 'morno' CHECK(temp IN ('quente','morno','frio')),priority text NOT NULL DEFAULT 'média' CHECK(priority IN ('alta','média','baixa')),owner_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES public.contacts(tenant_id,id),FOREIGN KEY(tenant_id,stage) REFERENCES public.pipeline_stages(tenant_id,id),FOREIGN KEY(tenant_id,owner_id) REFERENCES public.user_roles(tenant_id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.leads TO authenticated; GRANT ALL ON public.leads TO service_role;
ALTER TABLE public.leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY leads_members ON public.leads FOR ALL TO authenticated USING(public.is_member(tenant_id)) WITH CHECK(public.is_member(tenant_id));
CREATE TABLE public.lead_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,lead_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('msg','call','proposta','audio','pix','nota')),text text NOT NULL CHECK(length(text) BETWEEN 1 AND 4000),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,lead_id) REFERENCES public.leads(tenant_id,id) ON DELETE CASCADE);
GRANT SELECT,INSERT ON public.lead_events TO authenticated; GRANT ALL ON public.lead_events TO service_role;
ALTER TABLE public.lead_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY events_read ON public.lead_events FOR SELECT TO authenticated USING(public.is_member(tenant_id));
CREATE POLICY events_insert ON public.lead_events FOR INSERT TO authenticated WITH CHECK(public.is_member(tenant_id));
CREATE TABLE public.proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,lead_id uuid NOT NULL,base numeric NOT NULL CHECK(base BETWEEN 0 AND 999999999),discount numeric NOT NULL DEFAULT 0 CHECK(discount BETWEEN 0 AND 40),total numeric GENERATED ALWAYS AS (round(base*(1-discount/100),2)) STORED,status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,lead_id) REFERENCES public.leads(tenant_id,id) ON DELETE CASCADE);
GRANT SELECT,INSERT ON public.proposals TO authenticated; GRANT ALL ON public.proposals TO service_role;
ALTER TABLE public.proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY proposals_read ON public.proposals FOR SELECT TO authenticated USING(public.is_member(tenant_id));
CREATE POLICY proposals_insert ON public.proposals FOR INSERT TO authenticated WITH CHECK(public.is_member(tenant_id) AND status='draft' AND (discount<=15 OR public.is_tenant_admin(tenant_id) OR EXISTS(SELECT 1 FROM public.tenant_settings WHERE tenant_id=proposals.tenant_id AND structure='solo')));
CREATE TABLE public.commissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,lead_id uuid NOT NULL,user_id uuid NOT NULL,rate numeric NOT NULL CHECK(rate BETWEEN 0 AND 100),amount numeric NOT NULL CHECK(amount>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid')),UNIQUE(tenant_id,lead_id),FOREIGN KEY(tenant_id,lead_id) REFERENCES public.leads(tenant_id,id) ON DELETE CASCADE,FOREIGN KEY(tenant_id,user_id) REFERENCES public.user_roles(tenant_id,user_id));
GRANT SELECT,UPDATE(status) ON public.commissions TO authenticated; GRANT ALL ON public.commissions TO service_role;
ALTER TABLE public.commissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY commissions_read ON public.commissions FOR SELECT TO authenticated USING(public.is_tenant_admin(tenant_id) OR (public.is_member(tenant_id) AND user_id=auth.uid()));
CREATE POLICY commissions_update ON public.commissions FOR UPDATE TO authenticated USING(public.is_tenant_admin(tenant_id)) WITH CHECK(public.is_tenant_admin(tenant_id));
CREATE FUNCTION public.sync_commission() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r numeric; BEGIN NEW.updated_at=now(); IF NEW.stage='ganho' THEN SELECT commission_rate INTO r FROM public.tenant_settings WHERE tenant_id=NEW.tenant_id; INSERT INTO public.commissions(tenant_id,lead_id,user_id,rate,amount) VALUES(NEW.tenant_id,NEW.id,NEW.owner_id,r,round(NEW.value*r/100,2)) ON CONFLICT(tenant_id,lead_id) DO UPDATE SET user_id=excluded.user_id,amount=round(NEW.value*commissions.rate/100,2) WHERE commissions.status='pending'; ELSE DELETE FROM public.commissions WHERE tenant_id=NEW.tenant_id AND lead_id=NEW.id AND status='pending'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lead_commissions AFTER INSERT OR UPDATE ON public.leads FOR EACH ROW EXECUTE FUNCTION public.sync_commission();
CREATE TABLE public.tenant_invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants ON DELETE CASCADE,email text NOT NULL CHECK(length(email)<=254 AND email=lower(email)),token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',accepted_at timestamptz);
GRANT SELECT,INSERT,DELETE ON public.tenant_invitations TO authenticated; GRANT ALL ON public.tenant_invitations TO service_role;
ALTER TABLE public.tenant_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY invite_admin ON public.tenant_invitations FOR ALL TO authenticated USING(public.is_tenant_admin(tenant_id)) WITH CHECK(public.is_tenant_admin(tenant_id));
CREATE FUNCTION public.create_tenant(company_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; IF length(trim(company_name)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Invalid company'; END IF; INSERT INTO public.tenants(name) VALUES(trim(company_name)) RETURNING id INTO t; INSERT INTO public.user_roles(tenant_id,user_id,role) VALUES(t,auth.uid(),'admin'); INSERT INTO public.tenant_settings(tenant_id) VALUES(t); INSERT INTO public.pipeline_stages(tenant_id,id,label,position) VALUES(t,'novo','Novos',0),(t,'contato','Em contato',1),(t,'proposta','Proposta enviada',2),(t,'negociacao','Negociação',3),(t,'ganho','Ganho',4); RETURN t; END $$;
CREATE FUNCTION public.accept_invitation(invite_token uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.tenant_invitations; e text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Unauthorized'; END IF; SELECT email INTO e FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; SELECT * INTO i FROM public.tenant_invitations WHERE token=invite_token FOR UPDATE; IF i.id IS NULL OR i.accepted_at IS NOT NULL OR i.expires_at<=now() OR lower(e) IS DISTINCT FROM i.email THEN RAISE EXCEPTION 'Convite inválido, expirado ou destinado a outro e-mail'; END IF; INSERT INTO public.user_roles(tenant_id,user_id,role) VALUES(i.tenant_id,auth.uid(),'member') ON CONFLICT(tenant_id,user_id) DO NOTHING; UPDATE public.tenant_invitations SET accepted_at=now() WHERE id=i.id; RETURN i.tenant_id; END $$;
REVOKE ALL ON FUNCTION public.create_tenant(text),public.accept_invitation(uuid),public.create_profile(),public.sync_commission() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_tenant(text),public.accept_invitation(uuid) TO authenticated;
CREATE INDEX contacts_tenant ON public.contacts(tenant_id); CREATE INDEX leads_tenant ON public.leads(tenant_id); CREATE INDEX events_lead ON public.lead_events(tenant_id,lead_id); CREATE INDEX proposals_tenant ON public.proposals(tenant_id); CREATE INDEX commissions_tenant ON public.commissions(tenant_id); CREATE INDEX roles_user ON public.user_roles(user_id);